import React from 'react';
import { Link } from 'react-router-dom';
import './home.css'; // Updated to lowercase

const Home = () => {
  return (
    <div className="home-container">
      <div className="hero-section">
        <h1>Welcome to mmdai.in</h1>
        <p>Your trusted partner in financial services, equity broking, and industrial logistics.</p>

        {/* --- ACTION BUTTONS SECTION --- */}
        <div className="action-buttons-grid">

          <a href="PASTE_DEMAT_URL_HERE" target="_blank" rel="noopener noreferrer" className="btn btn-primary">
            Open Demat Account
          </a>

          <a href="PASTE_CONSULTATION_URL_HERE" target="_blank" rel="noopener noreferrer" className="btn btn-secondary">
            Request Consultation
          </a>

          <a href="PASTE_COAL_URL_HERE" target="_blank" rel="noopener noreferrer" className="btn btn-secondary">
            Coal Enquiry
          </a>

          <Link to="/contact-us" className="btn btn-outline">
            Contact Us
          </Link>

        </div>
        {/* ------------------------------- */}

      </div>

      {/* The rest of your home page content goes here... */}
    </div>
  );
};

export default Home; /* The component name can stay Capitalized, just the filename changes */
